(() => {
  const FIELDS = ["principal", "annualRate", "startDate", "endDate"];
  const MS_PER_DAY = 864e5;
  function parseDate(name, value) {
    if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
      throw new Error("invalid date: " + name);
    }
    const y = Number(value.slice(0, 4));
    const m = Number(value.slice(5, 7));
    const d = Number(value.slice(8, 10));
    const dt = new Date(0);
    dt.setUTCFullYear(y, m - 1, d);
    dt.setUTCHours(0, 0, 0, 0);
    if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== m - 1 || dt.getUTCDate() !== d) {
      throw new Error("invalid date: " + name);
    }
    return dt.getTime();
  }
  function round2(x) {
    const scaled = x * 100;
    if (Math.abs(scaled - Math.trunc(scaled)) === 0.5) {
      throw new Error("exact-half rounding pending REQ-4 confirmation");
    }
    return Math.round(scaled) / 100;
  }
  function simpleInterest(input) {
    if (input === null || typeof input !== "object") {
      throw new Error("invalid input");
    }
    for (const key of Object.keys(input)) {
      if (!FIELDS.includes(key)) {
        throw new Error("unknown field: " + key);
      }
    }
    const { principal, annualRate, startDate, endDate } = input;
    if (typeof principal !== "number" || !Number.isFinite(principal)) {
      throw new Error("invalid principal");
    }
    if (typeof annualRate !== "number" || !Number.isFinite(annualRate)) {
      throw new Error("invalid annualRate");
    }
    if (principal <= 0) {
      throw new Error("zero or negative principal pending REQ-5 confirmation");
    }
    if (annualRate <= 0) {
      throw new Error("zero or negative annualRate pending REQ-5 confirmation");
    }
    const start = parseDate("startDate", startDate);
    const end = parseDate("endDate", endDate);
    if (end < start) {
      throw new Error("end date before start date pending REQ-5 confirmation");
    }
    const days = Math.round((end - start) / MS_PER_DAY);
    const interest = round2(principal * annualRate * days / 365);
    return { days, interest };
  }
  return { simpleInterest };
})()

