build.unitScript:
test("31 days from 2026-03-01 to 2026-04-01 on 10000 at 6% gives 50.96 (AC-1)", () => {
  const r = code.simpleInterest({ principal: 1e4, annualRate: 0.06, startDate: "2026-03-01", endDate: "2026-04-01" });
  assert.deepEqual(r, { days: 31, interest: 50.96 });
});
test("leap February 2028-02-01 to 2028-03-01 counts 29 days and divides by 365 to give 47.67 (AC-2)", () => {
  const r = code.simpleInterest({ principal: 1e4, annualRate: 0.06, startDate: "2028-02-01", endDate: "2028-03-01" });
  assert.deepEqual(r, { days: 29, interest: 47.67 });
});
test("same start and end date gives 0 days and 0 interest (AC-3)", () => {
  const r = code.simpleInterest({ principal: 1e4, annualRate: 0.06, startDate: "2026-03-01", endDate: "2026-03-01" });
  assert.equal(r.days, 0);
  assert.equal(r.interest, 0);
});
test("next-day end date counts only the start day, giving 1 day and 1.64", () => {
  const r = code.simpleInterest({ principal: 1e4, annualRate: 0.06, startDate: "2026-03-01", endDate: "2026-03-02" });
  assert.deepEqual(r, { days: 1, interest: 1.64 });
});
test("whole leap year 2028 is 366 days over a 365 divisor, giving 601.64 not 600.00", () => {
  const r = code.simpleInterest({ principal: 1e4, annualRate: 0.06, startDate: "2028-01-01", endDate: "2029-01-01" });
  assert.deepEqual(r, { days: 366, interest: 601.64 });
});
test("an extra input field is rejected with unknown field and its name", () => {
  assert.throws(() => code.simpleInterest({ principal: 1e4, annualRate: 0.06, startDate: "2026-03-01", endDate: "2026-04-01", fee: 5 }), /^Error: unknown field: fee$/);
});

build.testScript:
test("returns interest 50.96 for principal 10000 at 6 percent from 2026-03-01 to 2026-04-01", function() {
  var result = code.simpleInterest({
    principal: 1e4,
    annualRate: 0.06,
    startDate: "2026-03-01",
    endDate: "2026-04-01"
  });
  assert.equal(result.interest, 50.96);
});
test("counts 31 days from 2026-03-01 to 2026-04-01 with the start included and the end excluded", function() {
  var result = code.simpleInterest({
    principal: 1e4,
    annualRate: 0.06,
    startDate: "2026-03-01",
    endDate: "2026-04-01"
  });
  assert.equal(result.days, 31);
});
test("returns 0 days and interest 0.00 when the start date and end date are the same", function() {
  var result = code.simpleInterest({
    principal: 1e4,
    annualRate: 0.06,
    startDate: "2026-03-01",
    endDate: "2026-03-01"
  });
  assert.equal(result.days, 0);
  assert.equal(result.interest, 0);
});
test("calculates interest as principal times rate times 31 days divided by 365 rounded to 50.96", function() {
  var result = code.simpleInterest({
    principal: 1e4,
    annualRate: 0.06,
    startDate: "2026-03-01",
    endDate: "2026-04-01"
  });
  assert.deepEqual(result, { days: 31, interest: 50.96 });
});
test("counts 29 days including 29 February and still divides by 365 to return 47.67", function() {
  var result = code.simpleInterest({
    principal: 1e4,
    annualRate: 0.06,
    startDate: "2028-02-01",
    endDate: "2028-03-01"
  });
  assert.equal(result.days, 29);
  assert.equal(result.interest, 47.67);
});
test("rounds 50.9589 to 50.96 and 47.6712 to 47.67", function() {
  var first = code.simpleInterest({
    principal: 1e4,
    annualRate: 0.06,
    startDate: "2026-03-01",
    endDate: "2026-04-01"
  });
  var second = code.simpleInterest({
    principal: 1e4,
    annualRate: 0.06,
    startDate: "2028-02-01",
    endDate: "2028-03-01"
  });
  assert.equal(first.interest, 50.96);
  assert.equal(second.interest, 47.67);
});

